package history

import (
	d "chnhcm.local/chnhcm/internal/contexts/organization/domain/department"
	"github.com/jackc/pgx/v5/pgtype"
	"slices"
	"strings"
)

// Parent queries consume the facts generated by the Go writer. They do not
// decode historical department structures or recompute storage seals. Required
// SQL values and source identity are ordinary adapter checks, not an audit.
func parentDepartment(enterprise string, fields []pgtype.Text) (d.Timeline, error) {
	if len(fields) != 14 {
		return d.Timeline{}, queryUnavailable()
	}
	for i, field := range fields {
		if i != 9 && i != 13 && !field.Valid {
			return d.Timeline{}, queryUnavailable()
		}
	}
	if fields[3].String != fields[5].String {
		return d.Timeline{}, queryUnavailable()
	}
	r := d.Record{ID: fields[6].String, Revision: fields[7].String,
		Date: fields[8].String, End: fields[9].String, State: fields[10].String,
		Data: d.Data{Name: fields[11].String, BU: fields[12].String, Parent: fields[13].String}}
	return d.Timeline{ID: fields[0].String, Code: fields[1].String, Enterprise: enterprise,
		First: fields[2].String, Source: fields[3].String, RelationSource: fields[4].String,
		Records: []d.Record{r}}, nil
}

type parentMaterialSet struct {
	departments map[string]d.Timeline
	bus         map[string]d.BusinessUnit
}

func (m *parentMaterialSet) add(s d.Snapshot) {
	if m.departments == nil {
		m.departments = map[string]d.Timeline{}
		m.bus = map[string]d.BusinessUnit{}
	}
	for _, t := range s.Departments {
		if old, ok := m.departments[t.ID]; ok {
			t.Records = append(old.Records, t.Records...)
		}
		m.departments[t.ID] = t
	}
	for _, b := range s.BusinessUnits {
		if old, ok := m.bus[b.ID]; ok {
			b.Records = append(old.Records, b.Records...)
		}
		m.bus[b.ID] = b
	}
}
func (m *parentMaterialSet) snapshot() d.Snapshot {
	s := d.Snapshot{}
	for _, t := range m.departments {
		slices.SortFunc(t.Records, func(a, b d.Record) int { return strings.Compare(a.Date, b.Date) })
		t.Records = slices.CompactFunc(t.Records, func(a, b d.Record) bool { return a.ID == b.ID })
		s.Departments = append(s.Departments, t)
	}
	for _, b := range m.bus {
		slices.SortFunc(b.Records, func(a, b d.BURecord) int { return strings.Compare(a.Date, b.Date) })
		b.Records = slices.CompactFunc(b.Records, func(a, b d.BURecord) bool { return a.ID == b.ID })
		s.BusinessUnits = append(s.BusinessUnits, b)
	}
	return s.Indexed()
}
